INSERT INTO tb_question
(title, difficulty, time_limit, space_limit, content, question_case, default_code, main_fuc, create_by, create_time, update_by, update_time)
VALUES
    ('数字反转', 2, 1000, 65536, '题目描述：\n给定一个整数 n，输出它的数字反转结果。\n\n示例 1：\n输入：123\n输出：321\n\n示例 2：\n输入：-456\n输出：-654\n\n提示：\n- n 为 int 范围内的整数。', '123|||321\n-456|||-654\n0|||0', 'class Solution {\n    public int reverseInt(int n) {\n        // TODO: 在这里编写你的代码\n    }\n}', 'import java.util.*;\nimport java.io.*;\nimport java.math.*;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        Solution s = new Solution();\n        System.out.println(s.reverseInt(n));\n    }\n}\n{{USER_CODE}}', 1, '2026-10-09 08:49:24', NULL, NULL),
    ('回文数判断', 2, 1000, 65536, '题目描述：\n给定一个整数 n，判断它是否为回文数。是输出 yes，否则输出 no。\n\n示例 1：\n输入：121\n输出：yes\n\n示例 2：\n输入：-121\n输出：no\n\n提示：\n- 负数不是回文数。', '121|||yes\n-121|||no\n0|||yes', 'class Solution {\n    public String isPalindrome(int n) {\n        // TODO: 在这里编写你的代码\n    }\n}', 'import java.util.*;\nimport java.io.*;\nimport java.math.*;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        Solution s = new Solution();\n        System.out.println(s.isPalindrome(n));\n    }\n}\n{{USER_CODE}}', 1, '2026-10-09 08:49:24', NULL, NULL),
    ('数组最大值', 1, 1000, 65536, '题目描述：\n第一行输入 n，第二行输入 n 个整数，输出最大值。\n\n示例 1：\n输入：5\n1 2 3 4 5\n输出：5\n\n提示：\n- 1 ≤ n ≤ 1000。', '5\n1 2 3 4 5|||5\n3\n-1 -2 -3|||-1', 'class Solution {\n    public int max(int[] arr) {\n        // TODO: 在这里编写你的代码\n    }\n}', 'import java.util.*;\nimport java.io.*;\nimport java.math.*;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] arr = new int[n];\n        for (int i = 0; i < n; i++) arr[i] = sc.nextInt();\n        Solution s = new Solution();\n        System.out.println(s.max(arr));\n    }\n}\n{{USER_CODE}}', 1, '2026-10-09 08:49:24', NULL, NULL),
    ('数组最小值', 1, 1000, 65536, '题目描述：\n第一行输入 n，第二行输入 n 个整数，输出最小值。\n\n示例 1：\n输入：5\n3 1 4 1 5\n输出：1\n\n提示：\n- 1 ≤ n ≤ 1000。', '5\n3 1 4 1 5|||1\n3\n-1 -2 -3|||-3', 'class Solution {\n    public int min(int[] arr) {\n        // TODO: 在这里编写你的代码\n    }\n}', 'import java.util.*;\nimport java.io.*;\nimport java.math.*;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] arr = new int[n];\n        for (int i = 0; i < n; i++) arr[i] = sc.nextInt();\n        Solution s = new Solution();\n        System.out.println(s.min(arr));\n    }\n}\n{{USER_CODE}}', 1, '2026-10-09 08:49:24', NULL, NULL),
    ('数组平均值', 2, 1000, 65536, '题目描述：\n第一行输入 n，第二行输入 n 个整数，输出它们的平均值（保留两位小数）。\n\n示例 1：\n输入：4\n1 2 3 4\n输出：2.50\n\n提示：\n- 使用 printf("%.2f") 输出。', '4\n1 2 3 4|||2.50\n2\n-1 1|||0.00', 'class Solution {\n    public double average(int[] arr) {\n        // TODO: 在这里编写你的代码\n    }\n}', 'import java.util.*;\nimport java.io.*;\nimport java.math.*;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] arr = new int[n];\n        for (int i = 0; i < n; i++) arr[i] = sc.nextInt();\n        Solution s = new Solution();\n        System.out.printf("%.2f%n", s.average(arr));\n    }\n}\n{{USER_CODE}}', 1, '2026-10-09 08:49:24', NULL, NULL),
    ('统计正数个数', 1, 1000, 65536, '题目描述：\n第一行输入 n，第二行输入 n 个整数，统计其中正数的个数。\n\n示例 1：\n输入：5\n-1 2 -3 4 5\n输出：3\n\n提示：\n- 1 ≤ n ≤ 1000。', '5\n-1 2 -3 4 5|||3\n3\n-1 -2 -3|||0', 'class Solution {\n    public int countPositive(int[] arr) {\n        // TODO: 在这里编写你的代码\n    }\n}', 'import java.util.*;\nimport java.io.*;\nimport java.math.*;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] arr = new int[n];\n        for (int i = 0; i < n; i++) arr[i] = sc.nextInt();\n        Solution s = new Solution();\n        System.out.println(s.countPositive(arr));\n    }\n}\n{{USER_CODE}}', 1, '2026-10-09 08:49:24', NULL, NULL),
    ('字符串长度', 1, 1000, 65536, '题目描述：\n给定一个字符串 s，输出它的长度。\n\n示例 1：\n输入：hello\n输出：5\n\n提示：\n- s 长度不超过 1000。', 'hello|||5\nabc|||3', 'class Solution {\n    public int length(String s) {\n        // TODO: 在这里编写你的代码\n    }\n}', 'import java.util.*;\nimport java.io.*;\nimport java.math.*;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String s = sc.next();\n        Solution solution = new Solution();\n        System.out.println(solution.length(s));\n    }\n}\n{{USER_CODE}}', 1, '2026-10-09 08:49:24', NULL, NULL),
    ('字符串转大写', 1, 1000, 65536, '题目描述：\n给定一个字符串 s（仅小写字母），输出它的大写形式。\n\n示例 1：\n输入：hello\n输出：HELLO\n\n提示：\n- 使用 toUpperCase()。', 'hello|||HELLO\nworld|||WORLD', 'class Solution {\n    public String toUpper(String s) {\n        // TODO: 在这里编写你的代码\n    }\n}', 'import java.util.*;\nimport java.io.*;\nimport java.math.*;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String s = sc.next();\n        Solution solution = new Solution();\n        System.out.println(solution.toUpper(s));\n    }\n}\n{{USER_CODE}}', 1, '2026-10-09 08:49:24', NULL, NULL),
    ('字符串转小写', 1, 1000, 65536, '题目描述：\n给定一个字符串 s（仅大写字母），输出它的小写形式。\n\n示例 1：\n输入：HELLO\n输出：hello\n\n提示：\n- 使用 toLowerCase()。', 'HELLO|||hello\nWORLD|||world', 'class Solution {\n    public String toLower(String s) {\n        // TODO: 在这里编写你的代码\n    }\n}', 'import java.util.*;\nimport java.io.*;\nimport java.math.*;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String s = sc.next();\n        Solution solution = new Solution();\n        System.out.println(solution.toLower(s));\n    }\n}\n{{USER_CODE}}', 1, '2026-10-09 08:49:24', NULL, NULL),
    ('字符串拼接', 2, 1000, 65536, '题目描述：\n给定两个字符串 a 和 b，输出 a + b 的结果。\n\n示例 1：\n输入：hello world\n输出：helloworld\n\n提示：\n- 使用 + 拼接。', 'hello world|||helloworld\nabc def|||abcdef', 'class Solution {\n    public String concat(String a, String b) {\n        // TODO: 在这里编写你的代码\n    }\n}', 'import java.util.*;\nimport java.io.*;\nimport java.math.*;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String a = sc.next();\n        String b = sc.next();\n        Solution s = new Solution();\n        System.out.println(s.concat(a, b));\n    }\n}\n{{USER_CODE}}', 1, '2026-10-09 08:49:24', NULL, NULL),
    ('字符出现次数', 2, 1000, 65536, '题目描述：\n给定字符串 s 和一个字符 c，统计 c 在 s 中出现的次数。\n\n示例 1：\n输入：hello l\n输出：2\n\n提示：\n- 遍历字符串比较。', 'hello l|||2\nabc a|||1', 'class Solution {\n    public int countChar(String s, char c) {\n        // TODO: 在这里编写你的代码\n    }\n}', 'import java.util.*;\nimport java.io.*;\nimport java.math.*;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String s = sc.next();\n        char c = sc.next().charAt(0);\n        Solution solution = new Solution();\n        System.out.println(solution.countChar(s, c));\n    }\n}\n{{USER_CODE}}', 1, '2026-10-09 08:49:24', NULL, NULL),
    ('判断闰年', 2, 1000, 65536, '题目描述：\n给定一个年份 y，判断是否为闰年。是输出 yes，否则输出 no。\n\n示例 1：\n输入：2020\n输出：yes\n\n提示：\n- 能被4整除且不能被100整除，或能被400整除。', '2020|||yes\n1900|||no\n2000|||yes', 'class Solution {\n    public String isLeap(int y) {\n        // TODO: 在这里编写你的代码\n    }\n}', 'import java.util.*;\nimport java.io.*;\nimport java.math.*;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int y = sc.nextInt();\n        Solution s = new Solution();\n        System.out.println(s.isLeap(y));\n    }\n}\n{{USER_CODE}}', 1, '2026-10-09 08:49:24', NULL, NULL),
    ('判断水仙花数', 2, 1000, 65536, '题目描述：\n给定一个三位数 n，判断是否为水仙花数（各位立方和等于本身）。是输出 yes，否则输出 no。\n\n示例 1：\n输入：153\n输出：yes\n\n提示：\n- 1^3 + 5^3 + 3^3 = 153。', '153|||yes\n370|||yes\n100|||no', 'class Solution {\n    public String isNarcissistic(int n) {\n        // TODO: 在这里编写你的代码\n    }\n}', 'import java.util.*;\nimport java.io.*;\nimport java.math.*;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        Solution s = new Solution();\n        System.out.println(s.isNarcissistic(n));\n    }\n}\n{{USER_CODE}}', 1, '2026-10-09 08:49:24', NULL, NULL),
    ('求和 1 到 n', 1, 1000, 65536, '题目描述：\n给定正整数 n，输出 1 + 2 + ... + n 的结果。\n\n示例 1：\n输入：10\n输出：55\n\n提示：\n- 1 ≤ n ≤ 10000。', '10|||55\n1|||1\n100|||5050', 'class Solution {\n    public int sumToN(int n) {\n        // TODO: 在这里编写你的代码\n    }\n}', 'import java.util.*;\nimport java.io.*;\nimport java.math.*;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        Solution s = new Solution();\n        System.out.println(s.sumToN(n));\n    }\n}\n{{USER_CODE}}', 1, '2026-10-09 08:49:24', NULL, NULL),
    ('阶乘和', 3, 1000, 65536, '题目描述：\n给定正整数 n，输出 1! + 2! + ... + n! 的结果。\n\n示例 1：\n输入：3\n输出：9\n\n提示：\n- 1 ≤ n ≤ 12。', '3|||9\n1|||1\n4|||33', 'class Solution {\n    public int factorialSum(int n) {\n        // TODO: 在这里编写你的代码\n    }\n}', 'import java.util.*;\nimport java.io.*;\nimport java.math.*;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        Solution s = new Solution();\n        System.out.println(s.factorialSum(n));\n    }\n}\n{{USER_CODE}}', 1, '2026-10-09 08:49:24', NULL, NULL),
    ('数字位数', 1, 1000, 65536, '题目描述：\n给定一个正整数 n，输出它的位数。\n\n示例 1：\n输入：12345\n输出：5\n\n提示：\n- 1 ≤ n ≤ 10^9。', '12345|||5\n7|||1\n100|||3', 'class Solution {\n    public int digits(int n) {\n        // TODO: 在这里编写你的代码\n    }\n}', 'import java.util.*;\nimport java.io.*;\nimport java.math.*;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        Solution s = new Solution();\n        System.out.println(s.digits(n));\n    }\n}\n{{USER_CODE}}', 1, '2026-10-09 08:49:24', NULL, NULL),
    ('数字各位和', 2, 1000, 65536, '题目描述：\n给定一个正整数 n，输出它各位数字之和。\n\n示例 1：\n输入：123\n输出：6\n\n提示：\n- 1 ≤ n ≤ 10^9。', '123|||6\n999|||27\n10|||1', 'class Solution {\n    public int digitSum(int n) {\n        // TODO: 在这里编写你的代码\n    }\n}', 'import java.util.*;\nimport java.io.*;\nimport java.math.*;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        Solution s = new Solution();\n        System.out.println(s.digitSum(n));\n    }\n}\n{{USER_CODE}}', 1, '2026-10-09 08:49:24', NULL, NULL),
    ('交换两个数', 1, 1000, 65536, '题目描述：\n输入两个整数 a 和 b，输出交换后的值，以空格分隔。\n\n示例 1：\n输入：1 2\n输出：2 1\n\n提示：\n- 使用临时变量交换。', '1 2|||2 1\n-5 10|||10 -5', 'class Solution {\n    public int[] swap(int a, int b) {\n        // TODO: 在这里编写你的代码\n    }\n}', 'import java.util.*;\nimport java.io.*;\nimport java.math.*;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int a = sc.nextInt();\n        int b = sc.nextInt();\n        Solution s = new Solution();\n        int[] res = s.swap(a, b);\n        System.out.println(res[0] + " " + res[1]);\n    }\n}\n{{USER_CODE}}', 1, '2026-10-09 08:49:24', NULL, NULL),
    ('判断正负零', 1, 1000, 65536, '题目描述：\n给定一个整数 n，输出 positive、negative 或 zero。\n\n示例 1：\n输入：5\n输出：positive\n\n提示：\n- n 为 int 范围内的整数。', '5|||positive\n-3|||negative\n0|||zero', 'class Solution {\n    public String sign(int n) {\n        // TODO: 在这里编写你的代码\n    }\n}', 'import java.util.*;\nimport java.io.*;\nimport java.math.*;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        Solution s = new Solution();\n        System.out.println(s.sign(n));\n    }\n}\n{{USER_CODE}}', 1, '2026-10-09 08:49:24', NULL, NULL),
    ('绝对值', 1, 1000, 65536, '题目描述：\n给定一个整数 n，输出它的绝对值。\n\n示例 1：\n输入：-5\n输出：5\n\n提示：\n- 使用 Math.abs()。', '-5|||5\n3|||3\n0|||0', 'class Solution {\n    public int abs(int n) {\n        // TODO: 在这里编写你的代码\n    }\n}', 'import java.util.*;\nimport java.io.*;\nimport java.math.*;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        Solution s = new Solution();\n        System.out.println(s.abs(n));\n    }\n}\n{{USER_CODE}}', 1, '2026-10-09 08:49:24', NULL, NULL);
