    ('求平方', 1, 1000, 65536, '题目描述：\n给定一个整数 n，输出 n 的平方。\n\n示例 1：\n输入：5\n输出：25\n\n提示：\n- 结果在 long 范围内。', '5|||25\n-3|||9\n0|||0', 'class Solution {\n    public long square(int n) {\n        // TODO: 在这里编写你的代码\n    }\n}', 'import java.util.*;\nimport java.io.*;\nimport java.math.*;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        Solution s = new Solution();\n        System.out.println(s.square(n));\n    }\n}\n{{USER_CODE}}', 1, '2026-10-09 08:49:24', NULL, NULL),
    ('求立方', 1, 1000, 65536, '题目描述：\n给定一个整数 n，输出 n 的立方。\n\n示例 1：\n输入：3\n输出：27\n\n提示：\n- 结果在 long 范围内。', '3|||27\n-2|||-8\n0|||0', 'class Solution {\n    public long cube(int n) {\n        // TODO: 在这里编写你的代码\n    }\n}', 'import java.util.*;\nimport java.io.*;\nimport java.math.*;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        Solution s = new Solution();\n        System.out.println(s.cube(n));\n    }\n}\n{{USER_CODE}}', 1, '2026-10-09 08:49:24', NULL, NULL),
    ('两数之积', 1, 1000, 65536, '题目描述：\n给定两个整数 a 和 b，输出它们的乘积。\n\n示例 1：\n输入：3 4\n输出：12\n\n提示：\n- 使用 long 防止溢出。', '3 4|||12\n-5 6|||-30\n0 100|||0', 'class Solution {\n    public long multiply(int a, int b) {\n        // TODO: 在这里编写你的代码\n    }\n}', 'import java.util.*;\nimport java.io.*;\nimport java.math.*;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int a = sc.nextInt();\n        int b = sc.nextInt();\n        Solution s = new Solution();\n        System.out.println(s.multiply(a, b));\n    }\n}\n{{USER_CODE}}', 1, '2026-10-09 08:49:24', NULL, NULL),
    ('两数之商', 2, 1000, 65536, '题目描述：\n给定两个整数 a 和 b，输出 a / b 的整数部分。\n\n示例 1：\n输入：10 3\n输出：3\n\n提示：\n- 保证 b 不为 0。', '10 3|||3\n-10 3|||-3\n7 7|||1', 'class Solution {\n    public int divide(int a, int b) {\n        // TODO: 在这里编写你的代码\n    }\n}', 'import java.util.*;\nimport java.io.*;\nimport java.math.*;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int a = sc.nextInt();\n        int b = sc.nextInt();\n        Solution s = new Solution();\n        System.out.println(s.divide(a, b));\n    }\n}\n{{USER_CODE}}', 1, '2026-10-09 08:49:24', NULL, NULL),
    ('两数之余', 2, 1000, 65536, '题目描述：\n给定两个整数 a 和 b，输出 a % b 的结果。\n\n示例 1：\n输入：10 3\n输出：1\n\n提示：\n- 保证 b 不为 0。', '10 3|||1\n-10 3|||-1\n7 7|||0', 'class Solution {\n    public int mod(int a, int b) {\n        // TODO: 在这里编写你的代码\n    }\n}', 'import java.util.*;\nimport java.io.*;\nimport java.math.*;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int a = sc.nextInt();\n        int b = sc.nextInt();\n        Solution s = new Solution();\n        System.out.println(s.mod(a, b));\n    }\n}\n{{USER_CODE}}', 1, '2026-10-09 08:49:24', NULL, NULL),
